package site.hsu.hub.file.application;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import site.hsu.hub.file.adapter.out.persistence.*;import site.hsu.hub.file.application.port.ObjectStorage;
@Component public class FileCleanupWorker{private final FileCleanupTaskRepository tasks;private final FileAssetRepository files;private final ObjectStorage objects;public FileCleanupWorker(FileCleanupTaskRepository tasks,FileAssetRepository files,ObjectStorage objects){this.tasks=tasks;this.files=files;this.objects=objects;}@Scheduled(fixedDelayString="${hsu.storage.cleanup-delay-ms:60000}")@Transactional public void retry(){for(var task:tasks.findTop20ByOrderByCreatedAtAsc()){try{objects.delete(task.objectKey());files.deleteById(task.fileAssetId());tasks.delete(task);}catch(RuntimeException e){task.attempted();}}}}
